  if(type==='sketch'&&feature.p.shape==='polygon')content+=`<label class="field full"><span>Profile vertices · [x, y] per line</span><textarea name="_points" rows="8" style="width:100%;border:1px solid #dce5eb;border-radius:4px;padding:7px;font-family:monospace;font-size:10px">${feature.p.points.map(p=>p.join(', ')).join('\n')}</textarea></label>`;
  content+='</form><div id="form-error"></div><div class="form-help">Inputs accept parameters and arithmetic: <code>baseWidth / 2</code>, <code>2 * cm</code>. Angles use degrees; lengths use millimeters.</div>';
  if(existing)content+=`<div class="feature-index">Feature ${state.doc.features.findIndex(f=>f.id===existing.id)+1} of ${state.doc.features.length}</div>`;
  panel('Feature editor',content,'<button class="secondary-button" data-action="preview-feature">Preview</button><button class="secondary-button" data-action="close-inspector">Cancel</button><button class="primary-button" data-action="apply-feature">Apply</button>');renderTimeline();renderer.invalidate();
